1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
3	const CURSE_SURCHARGE_RATE = 0.5;
4	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
5	const HIGH_ENCHANTMENT_THRESHOLD = 5;
6	const COMPONENT_BASE = 25;
7	const COMPONENT_BLOCK_BASE = 60;
8	const COMPONENT_BLOCK_SIZE = 3;
9	
10	const BASE_PREMIUM: Record<string, number> = {
11	  sword: 100,
12	  amulet: 60,
13	  staff: 80,
14	  potion: 40,
15	};
16	
17	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
18	
19	type Item = { type: string; cursed?: boolean; enchantment?: number };
20	type Step = { op: "quote"; items: Item[] };
21	type Scenario = { customer: { yearsWithMHPCO: number }; steps: Step[] };
22	
23	const basePremiumForComponentCount = (count: number): number =>
24	  count === COMPONENT_BLOCK_SIZE ? COMPONENT_BLOCK_BASE : count * COMPONENT_BASE;
25	
26	const countByType = (items: Item[]): Map<string, number> =>
27	  items.reduce(
28	    (counts, { type }) => counts.set(type, (counts.get(type) ?? 0) + 1),
29	    new Map<string, number>(),
30	  );
31	
32	const basePremiumForGroup = (type: string, count: number): number =>
33	  COMPONENT_TYPES.has(type) ? basePremiumForComponentCount(count) : count * BASE_PREMIUM[type];
34	
35	const basePremiumForItems = (items: Item[]): number =>
36	  [...countByType(items)].reduce(
37	    (sum, [type, count]) => sum + basePremiumForGroup(type, count),
38	    0,
39	  );
40	
41	const surchargeRateForItem = (item: Item): number =>
42	  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
43	  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
44	
45	const itemSurcharges = (items: Item[]): number =>
46	  items.reduce(
47	    (sum, item) => sum + basePremiumForGroup(item.type, 1) * surchargeRateForItem(item),
48	    0,
49	  );
50	
51	const roundInMHPCOsFavor = (premium: number): number => Math.ceil(premium);
52	
53	const withFirstInsuranceSurcharge = (base: number): number =>
54	  base + base * FIRST_INSURANCE_SURCHARGE_RATE;
55	
56	const quotePremium = (step: Step): number =>
57	  roundInMHPCOsFavor(
58	    withFirstInsuranceSurcharge(basePremiumForItems(step.items)) + itemSurcharges(step.items),
59	  ) + PROCESSING_FEE;
60	
61	export const runScenario = (scenario: Scenario): { results: Array<{ premium: number }> } => ({
62	  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
63	});
